using Microsoft.OpenApi;
using MiniErp.Api.Controllers;
using Swashbuckle.AspNetCore.SwaggerGen;

namespace MiniErp.Api.Swagger;

public sealed class CashVouchersSwaggerDocumentation : IOperationFilter
{
    public void Apply(
        OpenApiOperation operation,
        OperationFilterContext context)
    {
        if (context.MethodInfo.DeclaringType != typeof(CashVouchersController))
        {
            return;
        }

        var documentation = context.MethodInfo.Name switch
        {
            nameof(CashVouchersController.GetAll) => (
                "Get paginated cash vouchers",
                SwaggerOperationDescription.Create(
                    "Returns active manual and invoice-generated Receipt and Payment vouchers for the selected company. InvoiceId and InvoiceNumber identify generated payment vouchers.",
                    "Optional search, voucherNumber, direction, cashboxId, cashMovementTypeId, classification, partyType, businessPartnerId, driverId, driverTripId, employeeId, isDraft, fromDate, toDate, pageNumber, and pageSize filters.",
                    "Search covers voucher, cashbox, movement type, partner, driver, employee, trip invoice, external party, reference, and description display values. classification is persisted on the voucher; old rows are read with a movement-type/account fallback.",
                    "Deleted and other-company vouchers are excluded.")),
            nameof(CashVouchersController.GetHandoverReport) => (
                "Get cash handover report",
                SwaggerOperationDescription.Create(
                    "Returns manual cash-voucher drafts that are waiting for accounting completion. These drafts are operational custody records only and do not affect cashbox balances, partner statements, or the general ledger.",
                    "Optional cashboxId, fromDate, toDate, direction, search, pageNumber, and pageSize filters.",
                    "Search covers voucher number, cashbox code/name, description, and notes. Each draft item includes exchangeRate, baseAmount, and baseCurrency so a rate captured at handover remains visible. Receipt/payment/net summaries and expected cashbox balances use the cashbox currency amount.",
                    "Only drafts belonging to the selected company and not generated by an invoice or cashbox transfer are returned.")),
            nameof(CashVouchersController.GetById) => (
                "Get a cash voucher",
                SwaggerOperationDescription.Create(
                    "Returns one voucher with its draft status, optional cashbox, optional movement descriptor, optional expense/revenue account, party, optional source invoice, transaction/base amounts, resolved exchange-rate snapshot, and concurrency token.",
                    "A positive route id.",
                    "Currency is the selected cashbox currency. Completed vouchers and drafts saved with exchangeRate return a converted baseAmount/baseCurrency snapshot; base-currency rates must equal 1. Foreign-currency drafts saved without exchangeRate retain the unresolved placeholder exchangeRate=1 and baseAmount=0 until completion.",
                    "Missing or other-company vouchers return 404.")),
            nameof(CashVouchersController.GetPartySelect) => (
                "Get cash-voucher party selections",
                SwaggerOperationDescription.Create(
                    "Returns the active business partners, drivers, employees, expenses, and revenues available to cash vouchers for the selected company.",
                    "No request parameters.",
                    "Party collections contain id and name. expenses and revenues contain active posting accounts with id, name, classification, code, and accountType. Every collection is ordered by name then id. Active drivers remain available even when their license is expired.",
                    "Expense accounts are used with Payment vouchers and revenue accounts with Receipt vouchers. Movement descriptors are loaded separately from CashMovementTypes/select; inactive records are excluded.")),
            nameof(CashVouchersController.Create) => (
                "Create a cash voucher",
                SwaggerOperationDescription.Create(
                    "Requires Execute permission on the affected cashbox. Creates a manual cash handover draft linked to the selected active cashbox without accounting or cashbox-balance effects.",
                    "Send `voucherDate`, Receipt or Payment `direction`, an active `cashboxId`, a positive `amount`, and optional `exchangeRate`, `description`, or `notes`. No party, account, or movement type is required. A supplied exchangeRate must be positive with at most 12 decimal places; the company base currency accepts only 1.",
                    "`voucherNumber` is generated by the server. A supplied exchangeRate is saved on this draft with its converted baseAmount, without changing the shared exchange-rate table. Omitting it keeps the draft unresolved and does not require a registered rate. Complete the posting target later with PUT when the movement should enter the ledger.",
                    "The draft creates no journal, partner movement, employee movement, cashbox balance effect, or accounting-readiness source.")),
            nameof(CashVouchersController.Bulk) => (
                "Apply cash-voucher changes in bulk",
                SwaggerOperationDescription.Create(
                    "Requires Execute permission on the affected cashbox. Applies up to 100 ordered Add, Update, and Delete cash-voucher items as one atomic transaction.",
                    "Each item uses action as its discriminator. Add accepts action and voucher; Update accepts action, id, original base64 rowVersion, and voucher; Delete accepts action, id, and original base64 rowVersion only. cashMovementTypeId is optional for Add and Update.",
                    "The server generates voucher numbers and derives partyType from employeeId, businessPartnerId, driverId, or externalPartyName. For completion, send exactly one posting target from those fields or accountId; a mapped cashMovementTypeId may also be used as the counterpart target; cashMovementTypeId is an optional descriptor and must match the voucher direction. When employeeId is supplied, employeeMovementType is required and must match the direction (Credit/Bonus for Receipt, Debit/Deduction for Payment); it creates or updates the linked HR employee movement without duplication. An accountId must be an active posting Expense account for Payment or Revenue account for Receipt. An item cannot target an invoice-generated or cashbox-transfer-generated voucher. If any item fails, every item is rolled back.",
                    "An Add without a posting target saves an operational draft using the initial-create rules, with no cash balance or journal effect. A complete Add or an Update produces a completed, posted voucher, and updating a posted standalone voucher resynchronizes its journal and linked movements. Invoice-generated and transfer-generated vouchers remain read-only. Delete reverses the linked journal and movements and soft-deletes the standalone voucher. The response preserves request order and returns one result per request item. Any failure rolls back all prior items and identifies its Items[index] location.")),
            nameof(CashVouchersController.Update) => (
                "Classify, post, or update a cash voucher",
                SwaggerOperationDescription.Create(
                    "Requires Execute permission on the affected cashbox. Classifies and posts a manual draft, or updates and reposts an already-posted standalone voucher, including its saved base-currency snapshot and derived movements, atomically.",
                    "All voucher fields plus the original base64 rowVersion. Voucher number is server-generated, immutable, and is not sent. Send exactly one posting target: employeeId, businessPartnerId, driverId, externalPartyName, or accountId; an eligible mapped cashMovementTypeId can provide the counterpart target when no party or account is supplied. cashMovementTypeId is optional and can be sent with the target as an additional descriptor. driverTripId is allowed only with driverId. Partner settlements may use a different cashbox currency: amount and exchangeRate always describe the cashbox side. Optional partnerExchangeRate is company-base currency per unit of partner currency; if omitted the applicable company/fiscal-year daily rate is resolved (an existing manual partner snapshot is retained for the same partner/date). Base-currency partner rates must equal 1; same-currency partner rates must equal the cashbox rate. The response exposes partnerCurrency, partnerAmount, partnerExchangeRate and partnerBaseAmount. The partner native amount is rounded to cents and any rounding difference is posted separately through ExchangeGain/ExchangeLoss. POST drafts do not accept partnerExchangeRate; send it when completing through PUT or in posted bulk items.",
                    "The posting target allows cashMovementTypeId to be null. The server persists classification from the selected movement type, or Expense/Revenue from a direct account target, so expense screens can filter every source consistently. When supplied, the movement type must be active, match the voucher direction, and a partner-only type cannot be used with a non-partner target. For an employee target, employeeMovementType is required and must match the direction (Credit/Bonus for Receipt, Debit/Deduction for Payment); the linked HR movement is upserted by CashVoucherId. Use Receipt with Revenue account and Payment with Expense account. An explicit exchangeRate overrides the draft snapshot. Omitting it when completing a draft preserves its captured rate if currency and voucher date are unchanged; otherwise the registered rate for the selected currency/date is resolved. The applied rate and base amounts remain fixed after posting, even when a shared daily rate changes. Base-currency rates must equal 1.",
                    "Saving produces a completed, posted voucher. Updating an already-posted standalone voucher is allowed and resynchronizes its automatic journal entry and linked partner/employee movements; a stale token returns CashVouchers.Concurrency (409). Invoice-generated and transfer-generated vouchers keep their source-specific read-only errors and must be changed through the source document.")),
            nameof(CashVouchersController.UpdateDraft) => (
                "Save operational cash-voucher draft",
                SwaggerOperationDescription.Create(
                    "Requires Execute permission on the original and destination cashbox. Updates only an unposted standalone draft within its own open fiscal year, without cash balance, partner, employee, or journal effects.",
                    "Send voucherDate, direction, cashboxId, positive amount, original base64 rowVersion, and optional exchangeRate, description, referenceNumber, and notes. Currency is derived from the destination cashbox. The server preserves the number, company, and fiscal year.",
                    "A captured rate is retained only when currency and date are unchanged; an explicit rate is a voucher-local snapshot. Optional text fields use full replacement semantics. Classify and post separately with PUT /{id}.",
                    "Posted standalone vouchers return CashVouchers.PostedReadOnly (409). Stale draft revisions return CashVouchers.Concurrency (409). Invoice and transfer vouchers are edited through their source document.")),
            nameof(CashVouchersController.Delete) => (
                "Delete a standalone cash voucher",
                SwaggerOperationDescription.Create(
                    "Requires Execute permission on the affected cashbox. Deletes a standalone cash voucher, draft or posted.",
                    "A positive route id.",
                    "Reverses the linked automatic journal entry and removes the linked partner/employee movements, then soft-deletes the voucher. The fiscal year must be open.",
                    "Missing records return 404. Invoice-generated and transfer-generated vouchers retain their source-specific read-only errors.")),
            _ => default
        };

        if (documentation == default)
        {
            return;
        }

        operation.Summary = documentation.Item1;
        operation.Description = documentation.Item2;
        operation.OperationId = $"CashVouchers_{context.MethodInfo.Name}";
    }
}
